<div class="page-head"><div><h1><?= e($a['code']) ?> — <?= e($a['t_title']) ?></h1><p class="sub"><?= e(lname($a, 'dept')) ?><?= $a['branch_id'] ? ' / ' . e(lname($a, 'branch')) : '' ?> · <?= e($a['assessor_name']) ?> · <?= e(t('rcsa.due_date')) ?>: <?= e($a['due_date']) ?> · <?= status_badge($a['status']) ?></p></div><div class="actions"><a class="btn secondary" href="<?= e(url('rcsa')) ?>"><?= e(t('common.back')) ?></a></div></div>
<?php if ($a['review_comment']): ?><div class="msg info"><strong><?= e(t('rcsa.review_comment')) ?>:</strong> <?= e($a['review_comment']) ?> (<?= e($a['reviewer_name'] ?? '') ?> <?= e(fdatetime($a['reviewed_at'])) ?>)</div><?php endif; ?>
<section class="card"><h2><?= e(t('rcsa.summary')) ?></h2><p><?php foreach ($summary as $k => $n): ?><span class="badge"><?= e(t('enum.rating.' . $k)) ?>: <?= (int)$n ?></span> <?php endforeach; ?></p></section>
<form method="post" action="<?= e(url('rcsa/' . $a['id'] . '/save')) ?>" novalidate><?= csrf_field() ?>
<?php foreach ($qs as $i => $q): $qid = (int)$q['id']; $r = old('rating', [])[$qid] ?? $q['rating']; $c = old('comment', [])[$qid] ?? $q['comment']; $rk = old('risk', [])[$qid] ?? $q['risk_id']; ?>
<fieldset><legend><?= $i + 1 ?>. <?= e(lname($q, 'question')) ?></legend>
<?php if ($canRespond): ?>
<div class="form-grid"><div class="field<?= field_error('rating_' . $qid) ? ' has-error' : '' ?>"><label for="r<?= $qid ?>"><?= e(t('rcsa.rating')) ?></label><select id="r<?= $qid ?>" name="rating[<?= $qid ?>]"><option value=""><?= e(t('common.select')) ?></option><?php foreach (['effective', 'partially_effective', 'ineffective', 'not_applicable'] as $x): ?><option value="<?= $x ?>"<?= sel($r, $x) ?>><?= e(t('enum.rating.' . $x)) ?></option><?php endforeach; ?></select><?= field_error('rating_' . $qid) ?></div>
<div class="field<?= field_error('risk_' . $qid) ? ' has-error' : '' ?>"><label for="k<?= $qid ?>"><?= e(t('rcsa.linked_risk')) ?></label><select id="k<?= $qid ?>" name="risk[<?= $qid ?>]"><option value=""><?= e(t('common.none')) ?></option><?php foreach ($risks as $x): ?><option value="<?= (int)$x['id'] ?>"<?= sel($rk, $x['id']) ?>><?= e($x['risk_code'] . ' — ' . mb_strimwidth($x['title'], 0, 50, '…')) ?></option><?php endforeach; ?></select><?= field_error('risk_' . $qid) ?></div>
<div class="field wide<?= field_error('comment_' . $qid) ? ' has-error' : '' ?>"><label for="c<?= $qid ?>"><?= e(t('rcsa.comment')) ?></label><textarea id="c<?= $qid ?>" name="comment[<?= $qid ?>]" style="min-height:60px"><?= e($c) ?></textarea><?= field_error('comment_' . $qid) ?></div></div>
<?php else: ?><p><?= $q['rating'] ? status_badge($q['rating']) : '<span class="muted">' . e(t('enum.rating.unanswered')) . '</span>' ?> <?php if ($q['risk_id']): ?><a href="<?= e(url('risks/' . (int)$q['risk_id'])) ?>"><?= e(t('rcsa.linked_risk')) ?> #<?= (int)$q['risk_id'] ?></a><?php endif; ?></p><p class="pre"><?= e($q['comment'] ?? '') ?></p><?php endif; ?></fieldset>
<?php endforeach; ?>
<?php if ($canRespond): ?><div class="actions"><button class="btn secondary" type="submit"><?= e(t('rcsa.save_draft')) ?></button>
<button class="btn" type="submit" formaction="<?= e(url('rcsa/' . $a['id'] . '/submit')) ?>" data-confirm-msg><?= e(t('rcsa.submit')) ?></button></div><p class="hint"><?= e(t('rcsa.submit_hint')) ?></p><?php endif; ?></form>
<?php if ($canReview): ?><section class="card" style="margin-top:16px"><h2><?= e(t('rcsa.review')) ?></h2>
<form method="post" action="<?= e(url('rcsa/' . $a['id'] . '/review')) ?>" novalidate><?= csrf_field() ?>
<?= ff('select', 'decision', 'rcsa.decision', '', ['required' => true, 'options' => ['approve' => t('rcsa.approve'), 'return' => t('rcsa.return')]]) ?><?= ff('textarea', 'review_comment', 'rcsa.review_comment', '') ?>
<button class="btn" type="submit"><?= e(t('common.save')) ?></button></form></section><?php endif; ?>
